package cn.local.rainreminder;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.Build;import android.view.View;import android.widget.*;import java.util.*;

/** An exclusive page, not a floating layer over a live scrolling adapter. */
final class WidgetMenu {
 static List<RemoteViews> rows(Context c,int id){List<RemoteViews> out=new ArrayList<>();int selected=WidgetOptions.mode(c,id);String[] names={"课表优先","作业优先","仅课表","仅作业"};for(int mode=0;mode<4;mode++)out.add(row(c,(mode==selected?"✓  ":"     ")+names[mode],mode,-1,mode==selected));if(!WidgetOptions.homeworkFirst(selected)){int style=WidgetOptions.style(c,id);out.add(row(c,style==1?"切换为每日列表":"切换为周课表",-1,style==1?0:1,false));}return out;}
 static RemoteViews row(Context c,String title,int mode,int style,boolean selected){RemoteViews row=new RemoteViews(c.getPackageName(),R.layout.rain_widget_row);row.setTextViewText(R.id.widget_course_title,title);row.setTextViewTextSize(R.id.widget_course_title,android.util.TypedValue.COMPLEX_UNIT_SP,14);row.setViewVisibility(R.id.widget_course_detail,View.GONE);row.setInt(R.id.widget_course_area,"setMinimumHeight",Math.round(48*c.getResources().getDisplayMetrics().density));row.setInt(R.id.widget_course_area,"setBackgroundResource",selected?R.drawable.widget_action:R.drawable.widget_row_background);int pad=Math.round(12*c.getResources().getDisplayMetrics().density);row.setViewPadding(R.id.widget_course_area,pad,pad,pad,pad);row.setOnClickFillInIntent(R.id.widget_course_area,new Intent().putExtra("mode",mode).putExtra("style",style));return row;}
 static void bind(Context c,RemoteViews views,int id){Intent intent=new Intent(c,RainWidget.class).setAction(RainWidget.SWITCH).setData(android.net.Uri.parse("rainwidget://menu/choice/"+id)).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);views.setPendingIntentTemplate(R.id.widget_menu_options,PendingIntent.getBroadcast(c,0,intent,PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=31?PendingIntent.FLAG_MUTABLE:0)));if(Build.VERSION.SDK_INT>=31)Inline.bind(c,views,id);else views.setRemoteAdapter(R.id.widget_menu_options,new Intent(c,WidgetListService.class).putExtra("menu",true).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id).setData(android.net.Uri.parse("rainwidget://menu/data/"+id)));}
 static void visibility(Context c,RemoteViews views,int id){boolean open=WidgetOptions.menu(c,id);views.setViewVisibility(R.id.widget_root,open?View.GONE:View.VISIBLE);views.setViewVisibility(R.id.widget_menu,open?View.VISIBLE:View.GONE);views.setOnClickPendingIntent(R.id.widget_settings,RainWidget.menu(c,id));views.setOnClickPendingIntent(R.id.widget_menu_close,RainWidget.menu(c,id));views.setOnClickPendingIntent(R.id.widget_more_settings,RainWidget.settings(c,id));if(open)bind(c,views,id);}
 static void toggle(Context c,int id){WidgetOptions.menu(c,id,!WidgetOptions.menu(c,id));AppWidgetManager manager=AppWidgetManager.getInstance(c);android.os.Bundle options=manager.getAppWidgetOptions(id);int h=options.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,180),portrait=options.getInt(AppWidgetManager.OPTION_APPWIDGET_MAX_HEIGHT,h);long now=System.currentTimeMillis();manager.updateAppWidget(id,new RemoteViews(RainWidget.views(c,id,h,now),RainWidget.views(c,id,portrait,now)));if(Build.VERSION.SDK_INT<31)manager.notifyAppWidgetViewDataChanged(id,R.id.widget_menu_options);}
 static final class Inline {static void bind(Context c,RemoteViews views,int id){RemoteViews.RemoteCollectionItems.Builder builder=new RemoteViews.RemoteCollectionItems.Builder().setViewTypeCount(1).setHasStableIds(false);List<RemoteViews> rows=rows(c,id);for(int n=0;n<rows.size();n++)builder.addItem(n,rows.get(n));views.setRemoteAdapter(R.id.widget_menu_options,builder.build());}}
}
